// 날짜 문자열을 타임스탬프로 변환
function parseDateTime(str: string): number {
  // Format: "YYYY-MM-DD HH:MM:SS" (UTC)
  const [datePart, timePart] = str.split(' ');
  const [year, month, day] = datePart.split('-').map(Number);
  const [hour, minute, second] = timePart.split(':').map(s => parseInt(s, 10) || 0);
  return Date.UTC(year, month - 1, day, hour, minute, second);
}

// 캐시된 데이터
let cachedData: Record<number, number[]> | null = null;

export function getJeolgiData(): Record<number, number[]> {
  if (cachedData) return cachedData;
  
  cachedData = {};
  for (const [yearStr, terms] of Object.entries(RAW_DATA)) {
    const year = parseInt(yearStr, 10);
    cachedData[year] = terms.map(parseDateTime);
  }
  
  return cachedData;
}

export { RAW_DATA };
